/**
 * Test flow for deleteRecord action
 * Demonstrates deleting a record
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testDeleteRecord = Flow(
    {
        $id: Now.ID['test_delete_record_flow'],
        name: 'Test Delete Record',
        description: 'Tests the deleteRecord core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_delete_record_trigger'] },
        {
            table: 'incident',
            condition: 'short_description=DELETE_ME',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        wfa.action(
            action.core.deleteRecord,
            { $id: Now.ID['test_delete_record_action'] },
            {
                record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_delete_record_log'] },
            {
                log_level: 'info',
                log_message: `deleteRecord outputs: record=${wfa.dataPill(_params.trigger.current.sys_id, 'reference')}`,
            }
        )
    }
)
